if (tw.local.DBResult != null && tw.local.DBResult[0].rows != null && tw.local.DBResult[0].rows.listLength != 0) {
	for (var i=0; i<tw.local.DBResult[0].rows.listLength; i++) {
		tw.local.results[i] = new tw.object.NameValuePair(); 
		tw.local.results[i].value = tw.local.DBResult[0].rows[i].data[0].toString();
		tw.local.results[i].name = tw.local.DBResult[0].rows[i].data[1];
	}
}
